     {
         if (value == null)
         {
             return null;
         }

         if (value.Length == 0)
         {
             return value;
         }

         truncationString ??= string.Empty;

         if (truncationString.Length > length)
         {
             return truncateFrom == TruncateFrom.Right ? value[..length] : value[^length..];
         }

         var alphaNumericalCount = 0;
         foreach (var c in value)
         {
